-- 현재 지도에서 사용하는 tourist_landmarks: 기존 자료 유지, 중복 제외 후 추가
-- 원본: cityname_split/02_관광지.sql. 좌표와 시군구가 확인되는 자료만 포함.
SET NAMES utf8mb4;
USE `cityname`;

CREATE TABLE IF NOT EXISTS `tourist_landmarks` (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  region_code CHAR(2) NOT NULL,
  locality_name VARCHAR(50) NOT NULL,
  title VARCHAR(120) NOT NULL,
  description VARCHAR(255) NOT NULL,
  latitude DECIMAL(10,6) NOT NULL,
  longitude DECIMAL(10,6) NOT NULL,
  location_url VARCHAR(500) NOT NULL,
  source_name VARCHAR(100) NOT NULL,
  INDEX idx_lookup(region_code, locality_name),
  CONSTRAINT fk_tourist_landmarks_region FOREIGN KEY (region_code) REFERENCES regions(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TEMPORARY TABLE `cityname_tourism_import` LIKE `tourist_landmarks`;
START TRANSACTION;





SELECT p.region_code,p.locality_name,p.title,p.description,p.latitude,p.longitude,p.location_url,p.source_name
FROM `cityname_tourism_import` p
JOIN `regions` r ON r.code=p.region_code
WHERE NOT EXISTS (
 SELECT 1 FROM `tourist_landmarks` t
 WHERE t.region_code=p.region_code AND t.locality_name=p.locality_name
 AND REPLACE(t.title,' ','')=REPLACE(p.title,' ','')
 AND (t.source_name='프로젝트 예제 / OSM 위치 지도' OR (t.latitude BETWEEN p.latitude-0.00025 AND p.latitude+0.00025
 AND t.longitude BETWEEN p.longitude-0.00025 AND p.longitude+0.00025))
);
SELECT ROW_COUNT() AS added_rows;
COMMIT;
DROP TEMPORARY TABLE `cityname_tourism_import`;
